"""New v14 deterministic controls; all earlier evidence remains unchanged."""
import json
from pathlib import Path
import review13_sections as previous
from review11_sections import supplementary
ROOT=Path(__file__).resolve().parent.parent
LABELS={'legacy':'Baseline','shear-G':'Shear G','projected-energy':'Radial energy','centerline-energy':'Centre line'}
def add_section(doc,marker,paragraph,table,figure):
    if marker!='Q1_DISTANCE_V14':return previous.add_section(doc,marker,paragraph,table,figure)
    rows=json.loads((ROOT/'revision_14_2026-11-01/restricted_distance_records.json').read_text())
    summary=json.loads((ROOT/'revision_14_2026-11-01/restricted_distance_summary.json').read_text())
    nominal=[r for r in rows if r['n']==120 and r['phase_offset_steps']==0]
    paragraph(doc,'A further same-operator experiment measures the part of an isolated dedendum response that remains after refitting the addendum-only model. For G0 at 300 Nm, θ=(0.020,0.75,0.005,s_d) is evaluated at s_d=0.25 and 0.40 with each of the four compliance formulations. Synthetic observations are noiseless. The restricted fit fixes C_d=0 and the redundant s_d=0.50 and optimizes the two addendum coordinates with six bounded starts, including the true addendum coordinates and three fixed-seed random starts. Each formulation generates and fits its own response; this is an internal inferential control, not an independent validation.')
    paragraph(doc,'Canonical 120-, 240- and 480-position grids and a half-step-shifted 120-position grid assess phase dependence. All fits are evaluated on a common 960-position cycle, which includes the canonical fitting positions and is not an independent dataset. To compare objective scales without rewarding larger sample counts, we report D₁₂₀=120(RMS residual/0.1 µm)². This quantity is a descriptive noiseless distance at a fixed observation normalization, not a calibrated likelihood-ratio statistic or a test with established power. The linear projection of the isolated signal onto the complement of the addendum tangent is reported separately from the nonlinear bounded fit.')
    weak=[r for r in nominal if r['truth'][3]==.25];deep=[r for r in nominal if r['truth'][3]==.4]
    interval=lambda rr,k:f"{min(r[k] for r in rr):.6g}–{max(r[k] for r in rr):.6g}"
    paragraph(doc,'At 120 canonical positions, the restricted residual is '+interval(weak,'restricted_residual_rms_um')+' µm for s_d=0.25, with D₁₂₀='+interval(weak,'normalized_distance_120')+'. At s_d=0.40, the residual is '+interval(deep,'restricted_residual_rms_um')+' µm and D₁₂₀='+interval(deep,'normalized_distance_120')+' (Supplementary Table S22). The deeper-support case therefore remains separated from the addendum-only response set in each tested formulation. These positive distances are local multistart results; they do not prove global separation over every admissible profile or identify both dedendum coordinates uniquely.')
    paragraph(doc,'The phase-shift and refinement results in Supplementary Table S23 quantify the grid dependence directly rather than treating the 480-position grid as a convergence certificate. All '+str(summary['attempts'])+' attempted fits are retained; '+str(summary['failed_attempts'])+' report nonconvergence. The maximum independent iterative-versus-Lambert response difference is '+f"{summary['max_engine_difference_rms_um']:.3g}"+' µm RMS. The largest relative difference between the implicit tangent and central finite differences at the generating truths is '+f"{summary['max_jacobian_relative_error']:.3g}"+'. Thus the support-depth contrast persists when the shear law is corrected and across the tested energy formulations. This supports a qualitative operator-conditioned result; it does not close external mechanical discrepancy, FE phase omissions or physical inverse convergence.')
    figure(doc,'fig_restricted_distance_v14.png','Figure 11 Isolated dedendum signal and residual after a six-start addendum-only refit, for noiseless same-operator data at 300 Nm and 120 canonical phases. Each formulation generates its own observations. The shallow and deeper cases have different vertical scales. A nonzero restricted residual is not a certificate of unique four-parameter recovery.')
    supplementary('S22','Same-operator addendum compensation at 300 Nm and 120 canonical positions. D120 normalizes the noiseless squared residual to 120 observations and a 0.1 µm reference scale; it is not a calibrated significance statistic. The projected signal uses the addendum tangent at zero dedendum.',['Formulation','True s_d','Isolated µm','Projected µm','Refit RMS µm','D120'],[[LABELS[r['variant']],r['truth'][3],f"{r['isolated_signal_rms_um']:.6g}",f"{r['local_projected_signal_rms_um']:.6g}",f"{r['restricted_residual_rms_um']:.6g}",f"{r['normalized_distance_120']:.6g}"] for r in nominal],[3.1,1.5,2.8,2.8,3.1,3.1])
    grid=[]
    for r in nominal:
        rr=[x for x in rows if x['variant']==r['variant'] and x['truth']==r['truth']]
        vals=[next(x for x in rr if x['n']==n and x['phase_offset_steps']==o)['restricted_residual_rms_um'] for n,o in [(120,0),(120,.5),(240,0),(480,0)]]
        dense=next(x for x in rr if x['n']==480)['heldout_960_residual_rms_um']
        grid.append([LABELS[r['variant']],r['truth'][3],*[f'{v:.6g}' for v in vals],f'{dense:.6g}'])
    supplementary('S23','Sampling dependence of restricted residuals in µm RMS. Shifted 120 uses half a grid step. The final column evaluates the 480-position fit on a common 960-position grid that includes its fitting positions; generating and fitting operators are identical. A denser evaluation is not independent validation or a continuous-cycle convergence proof.',['Formulation','s_d','120','120 shifted','240','480','480 fit on 960'],grid,[2.8,1.1,2.4,2.8,2.4,2.4,2.9])
